  for (const e of events) {
    const data = e.data ?? {};
    const claimId = str(data.claimId);
    const base = {
      key: `e${e.seq}${isLiveEvent(e) ? "-live" : ""}`,
      seq: e.seq,
      stage: e.stage,
      type: e.type,
      at: e.at,
      provisional: isLiveEvent(e),
      held: false,
      event: e,
