export const itemKey = (runId: string, decisionId: string) =>
  `${runId}\n${decisionId}`;

export type PendingRow = {
  key: string;
  item: PendingApproval;
  bundle?: RunBundle;
  decision?: Decision;
};

export type DecidedRow = {
  key: string;
  record: ApprovalRecord;
  bundle?: RunBundle;
  decision?: Decision;
};

export type HistoryRow = {
  key: string;
  bundle: RunBundle;
  decision: Decision;
  /** Why this held item has no actions here. */
  note: string;
};

export type Desk = {
  mode: DeskMode;
  pending: PendingRow[];
  decided: DecidedRow[];
  /** Held decisions of the selected run that the desk doesn't list as pending or decided. */
  history: HistoryRow[];
  /** Pending items dropped because their run is fixture data (never approvable). */
  droppedSample: number;
};

export const heldDecisions = (bundle: RunBundle) =>
  bundle.decisions.filter((d) => d.status === "held");

/**
 * One desk from the server list (local mode only), every loaded bundle and the selected run.
 * Hosted mode ignores any list: there are no pending items and no actions, only history.
 */
export function buildDesk({
  mode,
  list,
  bundles,
  selected,
}: {
  mode: DeskMode;
  list?: ApprovalsList;
  bundles: RunBundle[];
  selected?: RunBundle;
}): Desk {
  const byRun = new Map(bundles.map((b) => [b.runId, b]));
  const lookup = (runId: string, decisionId: string) => {
    const bundle = byRun.get(runId);
    return { bundle, decision: bundle?.decisions.find((d) => d.id === decisionId) };
  };
  const local = mode === "local" ? list : undefined;
  let droppedSample = 0;
  const pending: PendingRow[] = [];
  for (const item of local?.pending ?? []) {
    const found = lookup(item.runId, item.decisionId);
    if (found.bundle?.sample) {
      droppedSample += 1;
      continue;
    }
    pending.push({ key: itemKey(item.runId, item.decisionId), item, ...found });
  }
  const decided: DecidedRow[] = (local?.decided ?? [])
    .map((record) => ({
      key: itemKey(record.runId, record.decisionId),
      record,
      ...lookup(record.runId, record.decisionId),
    }))
    .sort((a, b) => b.record.decidedAt.localeCompare(a.record.decidedAt));
  const listed = new Set([...pending, ...decided].map((r) => r.key));
  const history: HistoryRow[] = selected
    ? heldDecisions(selected)
        .filter((d) => !listed.has(itemKey(selected.runId, d.id)))
        .map((decision) => ({
          key: itemKey(selected.runId, decision.id),
          bundle: selected,
          decision,
          note: historyNote(mode, selected),
        }))
    : [];
  return { mode, pending, decided, history, droppedSample };
}

function historyNote(mode: DeskMode, bundle: RunBundle): string {
  if (bundle.sample) return RECORDED_RUN_NOTE;
  if (mode === "hosted") return "Recorded history. Decide it on a local `notary serve`.";
  return "Not listed by the local server: only verified, live, guarded runs under runs/ with a write action are approvable.";
}

/** "1,000 USD minor units" style text; the currency is shown only when recorded. */
export function minorUnitsText(
  amount: number,
  currency: string | undefined,
  format: (n: number) => string,
): string {
  return `${format(amount)}${currency ? ` ${currency}` : ""} minor units`;
}

// Replay only: the held decisions of the visible recorded runs, from DataSource.approvals() (the
// list the sidebar counts), one row per run. Visible = real runs, or fixture runs under the
// development-only ?fixtures=1 view (whose page header already carries the fixture disclosure);
// held decisions of hidden runs are never listed or counted.
import { useEffect, useState } from "react";
import { Link } from "react-router";
import { ArrowRightIcon as ArrowRight } from "@phosphor-icons/react/dist/csr/ArrowRight";
import { CheckCircleIcon as CheckCircle } from "@phosphor-icons/react/dist/csr/CheckCircle";
import type { ApprovalsList } from "../../../../core/src/schema";
import { EmptyState, Section, Skeleton } from "../../ui";
import { number } from "../../data";
import { useData } from "../../app/catalog";
import { withRun } from "../../app/links";

type State = { status: "loading" } | { status: "ready"; list: ApprovalsList } | { status: "error"; error: string };

export function RecordedHolds() {
  const { dataSource, bundles, selectedRunId } = useData();
  const [state, setState] = useState<State>({ status: "loading" });
  useEffect(() => {
    const controller = new AbortController();
    dataSource
      .approvals(controller.signal)
      .then((list) => !controller.signal.aborted && setState({ status: "ready", list }))
      .catch((e: Error) => !controller.signal.aborted && setState({ status: "error", error: e.message }));
    return () => controller.abort();
  }, [dataSource]);
  if (state.status === "loading")
    return (
      <div role="status" aria-live="polite">
        <span className="sr-only">Reading held decisions of the recorded runs…</span>
        <Skeleton shape="block" />
      </div>
    );
  if (state.status === "error")
    return (
      <EmptyState tone="error" title="Held decisions withheld">
        <p>The recorded runs’ held decisions could not be read. Re-export the runs with <code>pnpm notary export</code>.</p>
        <p className="desk-muted">{state.error}</p>
      </EmptyState>
    );
  const visible = new Set(bundles.map((b) => b.runId));
  const pending = state.list.pending.filter((item) => visible.has(item.runId));
  const perRun = new Map<string, number>();
  for (const item of pending) perRun.set(item.runId, (perRun.get(item.runId) ?? 0) + 1);
  const runs = [...perRun];
  return (
    <Section
      aria-labelledby="recorded-holds"
      title={<span id="recorded-holds">Held in recorded runs</span>}
      description={runs.length ? `${number(pending.length)} held ${pending.length === 1 ? "decision" : "decisions"} across ${number(runs.length)} ${runs.length === 1 ? "run" : "runs"}` : undefined}
    >
      {!runs.length ? (
        <EmptyState title="Nothing waiting for review.">No recorded run held a money action for a human.</EmptyState>
      ) : (
        <ul className="desk-runs" aria-label="Recorded runs with held decisions">
          {runs.map(([runId, count]) => {
            const selected = runId === selectedRunId;
            return (
              <li key={runId} className="desk-run" data-selected={selected || undefined} aria-current={selected ? "true" : undefined}>
                {selected ? (
                  <span className="desk-run-id">
                    <CheckCircle className="desk-run-icon" size={16} weight="regular" aria-hidden="true" />
                    <span>{runId}</span>
                    <span className="desk-run-tag">Selected · listed below</span>
                  </span>
                ) : (
                  <Link className="desk-run-id" to={withRun("/app/approvals", runId)}>
                    <ArrowRight className="desk-run-icon" size={16} weight="regular" aria-hidden="true" />
                    <span>{runId}</span>
                  </Link>
                )}
                <span className="desk-run-count">
                  <span className="num-display">{number(count)}</span> <span className="desk-run-unit">held</span>
                </span>
              </li>
            );
          })}
        </ul>
      )}
    </Section>
  );
}
// Shell-wide live status, read through the data layer:
//  - the local server's health, re-checked every 30 s and when the tab regains focus (live mode
//    only). The selection-time check alone could keep saying "Live" after `notary serve` stopped.
//  - the number of approvals waiting, from DataSource.approvals() (live: needs the session token;
//    replay: held decisions of the recorded runs). Undefined while unknown, never a placeholder 0.
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import type { HealthResponse } from "../../../../core/src/schema";
import { useDataSource, useSessionToken } from "../../data";
import { useOptionalData } from "../../app/catalog";

export const RECHECK_MS = 30_000;

export type LiveHealth =
  | { state: "replay" }
  | { state: "checking"; health: HealthResponse | null }
  | { state: "ok"; health: HealthResponse; checkedAt: string }
  | { state: "unreachable"; health: HealthResponse | null; checkedAt: string; error: string };

export type ApprovalsCount =
  | { state: "unknown"; reason: string }
  | { state: "ready"; pending: number; readOnly: boolean };

type ShellStatus = {
  health: LiveHealth;
  recheckHealth: () => void;
  approvals: ApprovalsCount;
  refreshApprovals: () => void;
};

const Ctx = createContext<ShellStatus | null>(null);

export function useShellStatus(): ShellStatus {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useShellStatus must be used within a ShellStatusProvider.");
  return ctx;
}

/** The shell status when rendered inside the shell; undefined in isolated renders (tests). */
export function useOptionalShellStatus(): ShellStatus | undefined {
  return useContext(Ctx) ?? undefined;
}

export function ShellStatusProvider({ children }: { children: ReactNode }) {
  const { source, mode, ready, health: selected } = useDataSource();
  const [token] = useSessionToken();
  const [health, setHealth] = useState<LiveHealth>(() =>
    mode === "live" ? { state: "checking", health: selected } : { state: "replay" },
  );
  const [healthKey, setHealthKey] = useState(0);
  const [approvals, setApprovals] = useState<ApprovalsCount>({ state: "unknown", reason: "Loading…" });
  const [approvalsKey, setApprovalsKey] = useState(0);
  const data = useOptionalData();
  const scoped = !!data;
  const visibleKey = data ? data.bundles.map((b) => b.runId).join("|") : "";
  const visibleIds = useMemo(() => new Set(visibleKey ? visibleKey.split("|") : []), [visibleKey]);

  useEffect(() => {
    if (!ready) return;
    if (mode !== "live") {
      setHealth({ state: "replay" });
      return;
    }
    const controller = new AbortController();
    setHealth((h) => (h.state === "ok" || h.state === "unreachable" ? h : { state: "checking", health: selected }));
    source
      .health(controller.signal)
      .then((h) => {
        if (controller.signal.aborted) return;
        if (h) setHealth({ state: "ok", health: h, checkedAt: new Date().toISOString() });
      })
      .catch((e: Error) => {
        if (controller.signal.aborted) return;
        setHealth((prev) => ({
          state: "unreachable",
          health: prev.state === "replay" ? null : prev.health,
          checkedAt: new Date().toISOString(),
          error: e.message,
        }));
      });
    return () => controller.abort();
  }, [source, mode, ready, selected, healthKey]);

  // Re-check on a timer and on focus, live mode only.
  useEffect(() => {
    if (!ready || mode !== "live") return;
    const recheck = () => setHealthKey((k) => k + 1);
    const timer = window.setInterval(recheck, RECHECK_MS);
    const onFocus = () => {
      if (document.visibilityState === "visible") recheck();
    };
    document.addEventListener("visibilitychange", onFocus);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", onFocus);
    };
  }, [ready, mode]);

  useEffect(() => {
    if (!ready) return;
    if (mode === "live" && !token) {
      setApprovals({ state: "unknown", reason: "Paste the session token on the Approvals page to see waiting items." });
      return;
    }
    const controller = new AbortController();
    source
      .approvals(controller.signal)
      .then((list) => {
        // Replay lists the held decisions of every published run; count only the visible ones (real
        // runs, or fixture runs under ?fixtures=1), so a fixture number never shows unlabeled.
        const pending =
          mode === "live" || !scoped ? list.pending.length : list.pending.filter((p) => visibleIds.has(p.runId)).length;
        if (!controller.signal.aborted) setApprovals({ state: "ready", pending, readOnly: mode !== "live" });
      })
      .catch((e: Error) => {
        if (!controller.signal.aborted) setApprovals({ state: "unknown", reason: e.message });
      });
    return () => controller.abort();
  }, [source, mode, ready, token, approvalsKey, visibleIds, scoped]);

  // Live mode: waiting items change as runs hold actions; refresh with the health re-check.
  useEffect(() => {
    if (mode === "live" && healthKey > 0) setApprovalsKey((k) => k + 1);
  }, [mode, healthKey]);

  const recheckHealth = useCallback(() => setHealthKey((k) => k + 1), []);
  const refreshApprovals = useCallback(() => setApprovalsKey((k) => k + 1), []);
  const value = useMemo(
    () => ({ health, recheckHealth, approvals, refreshApprovals }),
    [health, recheckHealth, approvals, refreshApprovals],
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

